INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('640', '51', '1', '1', 'speaking', 'intermediate', 'speaking_response', 'Speaking Practice 10', 'Read the following sentence aloud with clear pronunciation.', '{\"level\": \"intermediate\", \"title\": \"Speaking Practice 10\", \"prompt\": \"Indonesia is home to thousands of unique endemic species.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"keywords\": [\"endemik\", \"indonesia\", \"seperti\"], \"scenario\": \"Read the sentence aloud with clear pronunciation.\", \"min_words\": 35, \"competency\": \"Speaking · contextual response\", \"instruction\": \"Read the following sentence aloud with clear pronunciation.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\", \"example_response\": \"Indonesia is home to thousands of unique endemic species.\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Speaking · contextual response', 'fallback', '6051b58c4d2516f98f08879f83bbc9ba1689630217d2fb9a9bdbd880880796fb', 'ready', '2026-08-01 2