INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('641', '54', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 1', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 1\", \"prompt\": \"Imagine you are an explorer finding a new species in Kalimantan. Write a short story about your discovery. Answer: (1) Who did you go with? (2) What does the animal look like? (3) Where does it live? (4) Why is it unique? (5) How can we protect it?\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', 'd010bdb52702395137eef93981526ae4957d84b7a96b62c93b16c511ffe99286', 'ready', '2026-08-01 21:22:05');
INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('642', '55', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 2', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 2\", \"prompt\": \"Write a story about a day in the life of a Cendrawasih bird in the rainforest of Papua. In your story, cover: Who does it meet? What is it eating? Where is its nest? Why is it afraid of humans? How does it escape?\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', '7a523ede1b857877d2d1e17dee2cc21cfefc3c477f43519520703aea5ef8008d', 'ready', '2026-08-01 21:22:05');
INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('643', '56', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 3', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 3\", \"prompt\": \"Create a narrative story about Galang and his friends going birdwatching. Your story must answer the 5W+1H: Who went? What did they see? Where did they go? When did they start? Why did they go? How did they feel?\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', '8b75e67d0781e2f38471f2a90474cf45a711ef7c8fd8e23392ef947448856ec9', 'ready', '2026-08-01 21:22:05');
INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('644', '54', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 4', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 4\", \"prompt\": \"Imagine you are a wildlife conservation officer trying to save the Helmeted Hornbill. Write a short story about your rescue mission, explaining who you helped, what threat they faced, and how you solved it.\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', '29b6e23fbd31b9b068b755c39480219c56aa91dfb500d7e2907e7d53402cddc0', 'ready', '2026-08-01 21:22:05');
INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('645', '55', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 5', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 5\", \"prompt\": \"Write a paragraph about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds) by answering these questions: Who is responsible for protecting these animals? What is the main threat to their habitat? Where do they live? Why are they endemic?\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', 'a405e812ef62cc9a1df7500d5c7efc2822a0bce04233f197bd55f32f38c0ac87', 'ready', '2026-08-01 21:22:05');
INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('646', '56', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 6', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 6\", \"prompt\": \"Answer the following 5W+1H questions about the Bali Starling: Who is capturing them? What makes them attractive to poachers? Where do they live in the wild? Why are they critically endangered? How can we save them?\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', '49dde788c31192581f5d33c69fbdb75587b4507207968735f3ebe30d61d5ea64', 'ready', '2026-08-01 21:22:05');
INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('647', '54', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 7', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 7\", \"prompt\": \"Imagine you are a Bekantan (proboscis monkey) living in a mangrove forest. Write a story about a group of humans visiting your forest. Answer: Who are they? What are they doing? How do you feel?\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', '91ca12a91a8c15a83bce3f58e4c7dd6f698eeaaa1eb289cf14062c2c819484e4', 'ready', '2026-08-01 21:22:05');
INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('648', '55', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 8', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 8\", \"prompt\": \"Write a short story about an old wise bird in Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). In your story, explain: Who is the wise bird? What advice does it give to the younger birds? Where should they go to find safety?\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', 'a75ba033047842a7170520369724f27efcd8d11199534933710eb4bc8e57f506', 'ready', '2026-08-01 21:22:05');
INSERT INTO `learning_activities` (`id`, `module_id`, `classroom_id`, `lesson_plan_id`, `skill`, `level`, `activity_type`, `title`, `instruction`, `content_json`, `source_excerpt`, `competency`, `source`, `content_hash`, `status`, `created_at`) VALUES ('649', '56', '1', '1', 'writing', 'intermediate', 'writing_response', 'Writing Practice 9', 'Write a intermediate response within the word-count limit.', '{\"level\": \"intermediate\", \"title\": \"Writing Practice 9\", \"prompt\": \"Create a narrative about a student named Pipit who writes a blog post about endangered animals. Your story must answer: What animal does she write about? Why is it special? How do her friends help her?\", \"rubric\": [\"task_completion\", \"relevance\", \"grammar\", \"vocabulary\", \"organization\", \"coherence\", \"mechanics\"], \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 3. Indonesian Birds). You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"max_words\": 170, \"min_words\": 80, \"competency\": \"Writing · contextual response\", \"instruction\": \"Write a intermediate response within the word-count limit.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"source_excerpt\": \"SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star\"}', 'SOSIAL BUDAYA A. KONTEKS SOSIAL BUDAYA Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Starling (Bali). Konteks ini dipilih karena: Modul ini mengajak peserta didik mengeksplorasi burung-burung endemik Indonesia, seperti Cendrawasih (Papua), Helmeted Hornbill (Kalimantan), dan Bali Star', 'Writing · contextual response', 'fallback', '748af36651801107418f9d4b6109e4c34edee23a75829432f44941f5983c927e', 'ready', '2026-08-01 21:22:05');
