INSERT INTO `listening_sessions` (`id`, `classroom_id`, `member_id`, `lesson_plan_id`, `level`, `snapshot_json`, `current_position`, `score`, `replay_count`, `question_started_at`, `status`, `started_at`, `completed_at`) VALUES ('1', '2', '5', '4', 'intermediate', '{\"questions\": [{\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 8\", \"script\": \"Indonesia is home to thousands of endemic species found nowhere else in the world. These animals, like the Cendrawasih and Jalak Bali, are part of Indonesia\'s rich natural heritage.\", \"options\": [{\"id\": \"lo68_74476b18\", \"text\": \"Found all over the world\"}, {\"id\": \"lo68_83df0acc\", \"text\": \"Only found in one region\"}, {\"id\": \"lo68_d0eb28bc\", \"text\": \"A conservation method\"}, {\"id\": \"lo68_0159e872\", \"text\": \"A type of habitat\"}], \"language\": \"en-US\", \"question\": \"What does \\\\\\\"endemic\\\\\\\" mean?\", \"transcript\": \"Indonesia is home to thousands of endemic species found nowhere else in the world. These animals, like the Cendrawasih and Jalak Bali, are part of Indonesia\'s rich natural heritage.\", \"activity_id\": 68, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"B\", \"correct_option_id\": \"lo68_83df0acc\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 4\", \"script\": \"The Bali Starling is the national bird of Bali. It is known for its white feathers and blue eye-ring. Poaching for the illegal songbird trade is considered a major threat to its survival.\", \"options\": [{\"id\": \"lo64_f1e08eb7\", \"text\": \"Habitat destruction\"}, {\"id\": \"lo64_404a6b48\", \"text\": \"Poaching for illegal trade\"}, {\"id\": \"lo64_bf8f8ba7\", \"text\": \"Predators\"}, {\"id\": \"lo64_9324ad99\", \"text\": \"Climate change\"}], \"language\": \"en-US\", \"question\": \"What is the main threat to the Bali Starling?\", \"transcript\": \"The Bali Starling is the national bird of Bali. It is known for its white feathers and blue eye-ring. Poaching for the illegal songbird trade is considered a major threat to its survival.\", \"activity_id\": 64, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"C\", \"correct_option_id\": \"lo64_bf8f8ba7\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 7\", \"script\": \"Andre asked: \'What bird has a casque on its beak?\' Pipit answered: \'That\'s the Helmeted Hornbill!\' It is one of the rarest birds in Kalimantan.\", \"options\": [{\"id\": \"lo67_f8885114\", \"text\": \"The Cendrawasih\"}, {\"id\": \"lo67_8160951f\", \"text\": \"The Helmeted Hornbill\"}, {\"id\": \"lo67_a0ad5bc6\", \"text\": \"The Bekantan\"}, {\"id\": \"lo67_59ab5883\", \"text\": \"The Bali Starling\"}], \"language\": \"en-US\", \"question\": \"What bird does Pipit identify?\", \"transcript\": \"Andre asked: \'What bird has a casque on its beak?\' Pipit answered: \'That\'s the Helmeted Hornbill!\' It is one of the rarest birds in Kalimantan.\", \"activity_id\": 67, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"B\", \"correct_option_id\": \"lo67_8160951f\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 2\", \"script\": \"The Cendrawasih, or Bird of Paradise, is one of Indonesia\'s most beautiful birds. It lives in the rainforests of Papua. The male bird has bright, colourful feathers that are used to attract females.\", \"options\": [{\"id\": \"lo62_82cb57dc\", \"text\": \"Its casque\"}, {\"id\": \"lo62_feef3f1d\", \"text\": \"Bright colourful feathers\"}, {\"id\": \"lo62_bfc9bb02\", \"text\": \"Its white feathers\"}, {\"id\": \"lo62_eaf6abe4\", \"text\": \"Its large nose\"}], \"language\": \"en-US\", \"question\": \"What makes the Cendrawasih special?\", \"transcript\": \"The Cendrawasih, or Bird of Paradise, is one of Indonesia\'s most beautiful birds. It lives in the rainforests of Papua. The male bird has bright, colourful feathers that are used to attract females.\", \"activity_id\": 62, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"D\", \"correct_option_id\": \"lo62_eaf6abe4\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 1\", \"script\": \"The Bekantan, also known as the proboscis monkey, is found in the mangrove forests of Kalimantan. It has a very large nose and is only found in Borneo. Unfortunately, its habitat is being destroyed by deforestation.\", \"options\": [{\"id\": \"lo61_f2702c99\", \"text\": \"The highlands of Java\"}, {\"id\": \"lo61_4b817c8d\", \"text\": \"The rice fields of Sulawesi\"}, {\"id\": \"lo61_b6d7e261\", \"text\": \"The beaches of Bali\"}, {\"id\": \"lo61_176db961\", \"text\": \"Kalimantan mangrove forests\"}], \"language\": \"en-US\", \"question\": \"Where does the Bekantan live?\", \"transcript\": \"The Bekantan, also known as the proboscis monkey, is found in the mangrove forests of Kalimantan. It has a very large nose and is only found in Borneo. Unfortunately, its habitat is being destroyed by deforestation.\", \"activity_id\": 61, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"D\", \"correct_option_id\": \"lo61_176db961\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 10\", \"script\": \"Scientists study endangered animals to understand how to protect them. The Helmeted Hornbill is studied by ornithologists who want to preserve its habitat in the forests of Kalimantan.\", \"options\": [{\"id\": \"lo70_7507fd9a\", \"text\": \"Study animals to protect them\"}, {\"id\": \"lo70_6d7e8182\", \"text\": \"Manage national parks\"}, {\"id\": \"lo70_3019a8a4\", \"text\": \"Teach English in schools\"}, {\"id\": \"lo70_4fd1c57b\", \"text\": \"Hunt endangered species\"}], \"language\": \"en-US\", \"question\": \"What do ornithologists do?\", \"transcript\": \"Scientists study endangered animals to understand how to protect them. The Helmeted Hornbill is studied by ornithologists who want to preserve its habitat in the forests of Kalimantan.\", \"activity_id\": 70, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"A\", \"correct_option_id\": \"lo70_7507fd9a\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 6\", \"script\": \"Galang and his friends went birdwatching in the forest. Galang brought his binoculars, while Monita took notes in her notebook. They saw a Cendrawasih high up in the trees.\", \"options\": [{\"id\": \"lo66_70f65324\", \"text\": \"Binoculars\"}, {\"id\": \"lo66_68a920b0\", \"text\": \"A camera\"}, {\"id\": \"lo66_cf385206\", \"text\": \"A map\"}, {\"id\": \"lo66_cd43f3ff\", \"text\": \"A notebook\"}], \"language\": \"en-US\", \"question\": \"What did Galang bring on the birdwatching trip?\", \"transcript\": \"Galang and his friends went birdwatching in the forest. Galang brought his binoculars, while Monita took notes in her notebook. They saw a Cendrawasih high up in the trees.\", \"activity_id\": 66, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"A\", \"correct_option_id\": \"lo66_70f65324\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 3\", \"script\": \"The Helmeted Hornbill is a critically endangered bird found in Kalimantan. It is hunted for its casque, which is used to make carvings. Conservation programmes are being conducted to protect this species.\", \"options\": [{\"id\": \"lo63_85480d06\", \"text\": \"Habitat loss due to tourism\"}, {\"id\": \"lo63_e35c6f1e\", \"text\": \"Pollution in rivers\"}, {\"id\": \"lo63_25636132\", \"text\": \"Hunted for its casque\"}, {\"id\": \"lo63_96778ae7\", \"text\": \"Overfishing\"}], \"language\": \"en-US\", \"question\": \"Why is the Helmeted Hornbill endangered?\", \"transcript\": \"The Helmeted Hornbill is a critically endangered bird found in Kalimantan. It is hunted for its casque, which is used to make carvings. Conservation programmes are being conducted to protect this species.\", \"activity_id\": 63, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"B\", \"correct_option_id\": \"lo63_e35c6f1e\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 5\", \"script\": \"In this lesson, we learn about passive voice. For example: \'The Bekantan is found in Kalimantan.\' This sentence emphasises the subject, not the action.\", \"options\": [{\"id\": \"lo65_e23ae4a9\", \"text\": \"Scientists study the forest.\"}, {\"id\": \"lo65_16521a59\", \"text\": \"Birds live in Indonesia.\"}, {\"id\": \"lo65_c45ec062\", \"text\": \"The Bekantan is found in Kalimantan.\"}, {\"id\": \"lo65_3fd6297c\", \"text\": \"Galang finds the Bekantan.\"}], \"language\": \"en-US\", \"question\": \"Which sentence uses passive voice?\", \"transcript\": \"In this lesson, we learn about passive voice. For example: \'The Bekantan is found in Kalimantan.\' This sentence emphasises the subject, not the action.\", \"activity_id\": 65, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"C\", \"correct_option_id\": \"lo65_c45ec062\"}, {\"rate\": 1, \"pitch\": 1, \"title\": \"Listening Practice 9\", \"script\": \"A report text presents factual information about a subject in general. For example, a report about Cendrawasih would include its classification, habitat, diet, and threats.\", \"options\": [{\"id\": \"lo69_42800852\", \"text\": \"Give instructions\"}, {\"id\": \"lo69_cfd758fc\", \"text\": \"Tell a personal story\"}, {\"id\": \"lo69_b3f5ffc5\", \"text\": \"Present factual information generally\"}, {\"id\": \"lo69_6fe467e6\", \"text\": \"Describe one specific object\"}], \"language\": \"en-US\", \"question\": \"What is the purpose of a report text?\", \"transcript\": \"A report text presents factual information about a subject in general. For example, a report about Cendrawasih would include its classification, habitat, diet, and threats.\", \"activity_id\": 69, \"explanation\": \"Listen to the audio carefully to find the answer.\", \"correct_letter\": \"C\", \"correct_option_id\": \"lo69_b3f5ffc5\"}], \"correct_distribution\": {\"A\": 2, \"B\": 3, \"C\": 3, \"D\": 2}, \"sequence_fingerprint\": \"02dda118ef83235de517d8b2f5cf2f606676ab0516fad72288f1d4b91f06efd7\"}', '10', '50', '0', NULL, 'completed', '2026-08-02 17:04:02', '2026-08-02 17:07:44');
