INSERT INTO `quiz_answers` (`id`, `quiz_session_id`, `participant_id`, `session_question_id`, `selected_answer`, `is_correct`, `score`, `response_ms`, `answered_at`, `transcript`, `writing_submission`, `submission_method`, `assessment_status`, `rubric_json`, `normalized_score`, `assessment_source`) VALUES ('79', '25', '19', '115', NULL, '0', '980', '43905', '2026-08-02 14:46:46.950', NULL, 'Protecting the Cendrawasih bird involves greedy loggers destroying their forest homes, losing their shelter, flying to safer remote hills, teaching students about nature, and using school posters or clubs to share the message.The Threat and the ImpactWho: Illegal loggers and large companies cut down the tall trees in the deep jungle for wood and land.What: The bright birds lose their homes, their food sources disappear, and they struggle to find safe places to live.Survival and ActionWhere: The birds fly away to high, hidden mountain hills and thick parts of the jungle that people cannot reach easily.Why: Students must save them because these rare birds are a special part of nature that belongs only to our land.School CampaignsHow: Schools can make fun drawing boards, put up warning posters in hallways, and talk about saving birds during morning assembly.', 'editor', 'FALLBACK_COMPLETED', '{\"source\": \"fallback\", \"status\": \"completed\", \"criteria\": [{\"name\": \"task_completion\", \"score\": 85, \"feedback\": \"Fallback heuristic based on de-identified transcript text only.\", \"max_score\": 100}, {\"name\": \"relevance\", \"score\": 100, \"feedback\": \"Fallback heuristic based on de-identified transcript text only.\", \"max_score\": 100}, {\"name\": \"grammar\", \"score\": 100, \"feedback\": \"Fallback heuristic based on de-identified transcript text only.\", \"max_score\": 100}, {\"name\": \"vocabulary\", \"score\": 100, \"feedback\": \"Fallback heuristic based on de-identified transcript text only.\", \"max_score\": 100}, {\"name\": \"organization\", \"score\": 100, \"feedback\": \"Fallback heuristic based on de-identified transcript text only.\", \"max_score\": 100}, {\"name\": \"coherence\", \"score\": 100, \"feedback\": \"Fallback heuristic based on de-identified transcript text only.\", \"max_score\": 100}, {\"name\": \"mechanics\", \"score\": 100, \"feedback\": \"Fallback heuristic based on de-identified transcript text only.\", \"max_score\": 100}], \"strengths\": [\"A response was submitted successfully.\"], \"confidence\": 0.62, \"total_score\": 98, \"improvements\": [\"Add more precise details and varied sentence structures.\"], \"grammar_notes\": [\"Review sentence boundaries and verb consistency.\"], \"maximum_score\": 100, \"vocabulary_notes\": [\"Use more topic-specific vocabulary where appropriate.\"], \"suggested_revision\": \"Protecting the Cendrawasih bird involves greedy loggers destroying their forest homes, losing their shelter, flying to safer remote hills, teaching students about nature, and using school posters or clubs to share the message.The Threat and the ImpactWho: Illegal loggers and large companies cut down the tall trees in the deep jungle for wood and land.What: The bright birds lose their homes, their food sources disappear, and they struggle to find safe places to live.Survival and ActionWhere: The birds fly away to high, hidden mountain hills and thick parts of the jungle that people cannot reach easily.Why: Students must save them because these rare birds are a special part of nature that belongs only to our land.School CampaignsHow: Schools can make fun drawing boards, put up warning posters in hallways, and talk about saving birds during morning assembly. Add one clear supporting detail and a concluding sentence.\"}', '980', 'fallback');
