INSERT INTO `speaking_sessions` (`id`, `classroom_id`, `member_id`, `lesson_plan_id`, `level`, `task_snapshot_json`, `current_position`, `status`, `started_at`, `completed_at`, `task_started_at`, `task_deadline_at`, `recording_started_at`) VALUES ('3', '2', '5', '4', 'intermediate', '[{\"id\": 102, \"type\": \"guided_response\", \"title\": \"Speaking Practice 2\", \"prompt\": \"Cendrawasih is known for its bright ornamental feathers.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"konteks, sosial, modul\", \"position\": 0, \"instruction\": \"Jawablah pertanyaan berikut dalam bahasa Inggris. Gunakan kata bantuan jika diperlukan.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 110, \"type\": \"guided_response\", \"title\": \"Speaking Practice 10\", \"prompt\": \"Indonesia is home to thousands of unique endemic species.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"endemik, indonesia, bekantan\", \"position\": 1, \"instruction\": \"Jelaskan jawabanmu dalam bahasa Inggris dengan memakai kata bantuan yang tersedia.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 108, \"type\": \"guided_response\", \"title\": \"Speaking Practice 8\", \"prompt\": \"Sangihe shrike-thrush is a critically endangered bird.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"mengeksplorasi, satwa, endemik\", \"position\": 2, \"instruction\": \"Berikan respons singkat dalam bahasa Inggris berdasarkan pertanyaan berikut.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 109, \"type\": \"guided_response\", \"title\": \"Speaking Practice 9\", \"prompt\": \"Mangrove forests protect the coastal area from erosion.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"satwa, endemik, indonesia\", \"position\": 3, \"instruction\": \"Ceritakan kembali informasi berikut secara singkat dalam bahasa Inggris.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 105, \"type\": \"guided_response\", \"title\": \"Speaking Practice 5\", \"prompt\": \"The sumatran tiger has beautiful dark stripes on its body.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"mengajak, peserta, didik\", \"position\": 4, \"instruction\": \"Bandingkan gagasan pada pertanyaan berikut menggunakan bahasa Inggris.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 106, \"type\": \"guided_response\", \"title\": \"Speaking Practice 6\", \"prompt\": \"The flores hawk-eagle is one of the rarest raptors in Indonesia.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"peserta, didik, mengeksplorasi\", \"position\": 5, \"instruction\": \"Jawablah pertanyaan berikut dalam bahasa Inggris. Gunakan kata bantuan jika diperlukan.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 104, \"type\": \"guided_response\", \"title\": \"Speaking Practice 4\", \"prompt\": \"Illegal hunting and habitat loss threaten the survival of the Javan rhino.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"modul, mengajak, peserta\", \"position\": 6, \"instruction\": \"Jelaskan jawabanmu dalam bahasa Inggris dengan memakai kata bantuan yang tersedia.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 103, \"type\": \"guided_response\", \"title\": \"Speaking Practice 3\", \"prompt\": \"The maleo buries its eggs in the warm volcanic sand.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"sosial, modul, mengajak\", \"position\": 7, \"instruction\": \"Berikan respons singkat dalam bahasa Inggris berdasarkan pertanyaan berikut.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 107, \"type\": \"guided_response\", \"title\": \"Speaking Practice 7\", \"prompt\": \"We must protect the helmeted hornbill from illegal trade.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"didik, mengeksplorasi, satwa\", \"position\": 8, \"instruction\": \"Ceritakan kembali informasi berikut secara singkat dalam bahasa Inggris.\", \"target_text\": \"\", \"sentence_starter\": \"\"}, {\"id\": 101, \"type\": \"guided_response\", \"title\": \"Speaking Practice 1\", \"prompt\": \"The bekantan lives in the mangrove forests of Kalimantan.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"budaya, konteks, sosial\", \"position\": 9, \"instruction\": \"Bandingkan gagasan pada pertanyaan berikut menggunakan bahasa Inggris.\", \"target_text\": \"\", \"sentence_starter\": \"\"}]', '3', 'active', '2026-08-02 17:09:34', NULL, '2026-08-02 17:34:44', '2026-08-02 17:35:09', '2026-08-02 17:34:48');
INSERT INTO `speaking_sessions` (`id`, `classroom_id`, `member_id`, `lesson_plan_id`, `level`, `task_snapshot_json`, `current_position`, `status`, `started_at`, `completed_at`, `task_started_at`, `task_deadline_at`, `recording_started_at`) VALUES ('4', '2', '5', '4', 'basic', '[{\"id\": 1331, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 1\", \"prompt\": \"The bekantan lives in the mangrove forests of Kalimantan.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 0, \"instruction\": \"Bacalah kalimat bahasa Inggris berikut dengan jelas.\", \"target_text\": \"The bekantan lives in the mangrove forests of Kalimantan.\", \"sentence_starter\": \"\"}, {\"id\": 1338, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 8\", \"prompt\": \"Sangihe shrike-thrush is a critically endangered bird.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 1, \"instruction\": \"Bacalah dua kalimat pendek berikut dengan intonasi yang baik.\", \"target_text\": \"Sangihe shrike-thrush is a critically endangered bird.\", \"sentence_starter\": \"\"}, {\"id\": 1337, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 7\", \"prompt\": \"We must protect the helmeted hornbill from illegal trade.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 2, \"instruction\": \"Bacalah bagian berikut seolah-olah kamu sedang berbicara dengan teman.\", \"target_text\": \"We must protect the helmeted hornbill from illegal trade.\", \"sentence_starter\": \"\"}, {\"id\": 1332, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 2\", \"prompt\": \"This lesson discusses konteks, sosial, modul.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 3, \"instruction\": \"Bacalah kalimat deskriptif berikut dengan pelafalan yang jelas.\", \"target_text\": \"This lesson discusses konteks, sosial, modul.\", \"sentence_starter\": \"\"}, {\"id\": 1335, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 5\", \"prompt\": \"The words mengajak, peserta, didik are important in this lesson.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 4, \"instruction\": \"Bacalah kalimat berikut dengan ritme yang tenang dan jelas.\", \"target_text\": \"The words mengajak, peserta, didik are important in this lesson.\", \"sentence_starter\": \"\"}, {\"id\": 1333, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 3\", \"prompt\": \"Student: I can explain sosial, modul, mengajak in English.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 5, \"instruction\": \"Bacalah kalimat berikut sambil memperhatikan setiap kata.\", \"target_text\": \"Student: I can explain sosial, modul, mengajak in English.\", \"sentence_starter\": \"\"}, {\"id\": 1339, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 9\", \"prompt\": \"Mangrove forests protect the coastal area from erosion.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 6, \"instruction\": \"Bacalah kalimat bahasa Inggris berikut dengan jelas.\", \"target_text\": \"Mangrove forests protect the coastal area from erosion.\", \"sentence_starter\": \"\"}, {\"id\": 1336, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 6\", \"prompt\": \"The flores hawk-eagle is one of the rarest raptors in Indonesia.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 7, \"instruction\": \"Bacalah dua kalimat pendek berikut dengan intonasi yang baik.\", \"target_text\": \"The flores hawk-eagle is one of the rarest raptors in Indonesia.\", \"sentence_starter\": \"\"}, {\"id\": 1334, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 4\", \"prompt\": \"Illegal hunting and habitat loss threaten the survival of the Javan rhino.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 8, \"instruction\": \"Bacalah bagian berikut seolah-olah kamu sedang berbicara dengan teman.\", \"target_text\": \"Illegal hunting and habitat loss threaten the survival of the Javan rhino.\", \"sentence_starter\": \"\"}, {\"id\": 1340, \"type\": \"read_aloud\", \"title\": \"Speaking Practice 10\", \"prompt\": \"This lesson discusses endemik, indonesia, bekantan.\", \"rubric\": [\"response_relevance\", \"task_completion\", \"grammar\", \"vocabulary\", \"completeness\", \"transcription_clarity\"], \"guidance\": \"\", \"position\": 9, \"instruction\": \"Bacalah kalimat deskriptif berikut dengan pelafalan yang jelas.\", \"target_text\": \"This lesson discusses endemik, indonesia, bekantan.\", \"sentence_starter\": \"\"}]', '10', 'completed', '2026-08-02 17:18:07', '2026-08-02 17:34:43', NULL, NULL, NULL);
