INSERT INTO `writing_sessions` (`id`, `classroom_id`, `member_id`, `lesson_plan_id`, `level`, `task_snapshot_json`, `current_position`, `status`, `task_started_at`, `task_deadline_at`, `started_at`, `completed_at`, `sequence_fingerprint`) VALUES ('1', '2', '5', '4', 'intermediate', '[{\"id\": 71, \"type\": \"guided_writing\", \"prompt\": \"Write a short report about a specific animal mentioned in the lesson. Include its habitat, physical description, and one threat it faces.\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 0, \"max_chars\": 600, \"fingerprint\": \"9057f9ad925501d41cc36f4cb443005f99f276f5e39d8364992978552c2eb928\", \"instruction\": \"Tulislah dua kalimat singkat menggunakan bantuan yang tersedia.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 74, \"type\": \"guided_writing\", \"prompt\": \"Compare two animals from the lesson. Describe their similarities and differences in terms of habitat, appearance, and behavior.\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 1, \"max_chars\": 600, \"fingerprint\": \"af82d502f8e6afa2b910ff0bdb48495df07609d703559564e56249b2a02dd73c\", \"instruction\": \"Jelaskan jawabanmu dalam dua kalimat bahasa Inggris.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 78, \"type\": \"guided_writing\", \"prompt\": \"Write a fact file about one animal from the lesson: name, classification, habitat, diet, and threats.\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 2, \"max_chars\": 600, \"fingerprint\": \"a12b6d9f90185babd7af6342e779687f747f218e4da26bc2b7909f1209c23f43\", \"instruction\": \"Lanjutkan gagasan berikut secara singkat.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 72, \"type\": \"guided_writing\", \"prompt\": \"Describe what passive voice is and write three example sentences using passive voice about animals from the lesson.\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 3, \"max_chars\": 600, \"fingerprint\": \"017eaa73091eb4fb426d95674e5a99c701b77563c0cb541ad6cf70ee307421bc\", \"instruction\": \"Tulislah dua kalimat sin