INSERT INTO `writing_sessions` (`id`, `classroom_id`, `member_id`, `lesson_plan_id`, `level`, `task_snapshot_json`, `current_position`, `status`, `task_started_at`, `task_deadline_at`, `started_at`, `completed_at`, `sequence_fingerprint`) VALUES ('4', '2', '5', '4', 'advanced', '[{\"id\": 1384, \"type\": \"short_open_response\", \"prompt\": \"Imagine you are a wildlife conservation officer trying to save the Helmeted Hornbill. Write a short story about your rescue mission, explaining who you helped, what threat they faced, and how you solved it.\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 0, \"max_chars\": 900, \"fingerprint\": \"af377ed8fec28216ad3ca54855199d936a75723703b4290fbb6a247901e16ea1\", \"instruction\": \"Tulislah pendapat singkat dalam dua sampai tiga kalimat.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1386, \"type\": \"short_open_response\", \"prompt\": \"Answer the following 5W+1H questions about the Bali Starling: Who is capturing them? What makes them attractive to poachers? Where do they live in the wild? Why are they critically endangered? How can we save them?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 1, \"max_chars\": 900, \"fingerprint\": \"d18933085d8c179cf120e944261194b1b972375d50ea14cbe56a2cb02e28bc1f\", \"instruction\": \"Jelaskan alasan atau solusi secara ringkas.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1388, \"type\": \"short_open_response\", \"prompt\": \"Write a short story about an old wise bird in Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. In your story, explain: Who is the wise bird? What advice does it give to the younger birds? Where should they go to find safety?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 2, \"max_chars\": 900, \"fingerprint\": \"c3b432063f0260a6cc227793df946c13d00dbe475acd82b20c9ee5e128a26a59\", \"instruction\": \"Berikan rekomendasi singkat dalam bahasa Inggris.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1385, \"type\": \"short_open_response\", \"prompt\": \"Write a paragraph about Chapter 1 - Exploring Fauna of Indonesia (Unit 1. by answering these questions: Who is responsible for protecting these animals? What is the main threat to their habitat? Where do they live? Why are they endemic?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 3, \"max_chars\": 900, \"fingerprint\": \"8e5e9bd9d3af80b90d0b8d6bf0eca074cc5125dd4a21189f7e7e2747542b4d98\", \"instruction\": \"Tulislah pendapat singkat dalam dua sampai tiga kalimat.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1387, \"type\": \"short_open_response\", \"prompt\": \"Imagine you are a Bekantan (proboscis monkey) living in a mangrove forest. Write a story about a group of humans visiting your forest. Answer: Who are they? What are they doing? How do you feel?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 4, \"max_chars\": 900, \"fingerprint\": \"201ab8a3d35417b0095e42cc7d6171da47cfdc1f83d53dfe3f1cedb22d02ec30\", \"instruction\": \"Jelaskan alasan atau solusi secara ringkas.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1390, \"type\": \"short_open_response\", \"prompt\": \"Answer the 5W+1H questions to write a descriptive report on Indonesian fauna: Who is studying them? What characteristics do they share? Where are they found? Why are they endangered? How do we conserve them?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 5, \"max_chars\": 900, \"fingerprint\": \"9e8b366d6661daf258692badf4525996c9d600e318f3835d4a0c1bbc3dacf853\", \"instruction\": \"Berikan rekomendasi singkat dalam bahasa Inggris.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1382, \"type\": \"short_open_response\", \"prompt\": \"Write a story about a day in the life of a Cendrawasih bird in the rainforest of Papua. In your story, cover: Who does it meet? What is it eating? Where is its nest? Why is it afraid of humans? How does it escape?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 6, \"max_chars\": 900, \"fingerprint\": \"9bd23f0f322b58d5a86ee54c319c83e8ffb0e35b8a0dc66189c7339313968184\", \"instruction\": \"Tulislah pendapat singkat dalam dua sampai tiga kalimat.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1381, \"type\": \"short_open_response\", \"prompt\": \"Imagine you are an explorer finding a new species in Kalimantan. Write a short story about your discovery. Answer: (1) Who did you go with? (2) What does the animal look like? (3) Where does it live? (4) Why is it unique? (5) How can we protect it?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 7, \"max_chars\": 900, \"fingerprint\": \"db74cea3fccd48bf8d3019d916c0939101da8d0736cf032faca57dc49a344d15\", \"instruction\": \"Jelaskan alasan atau solusi secara ringkas.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1383, \"type\": \"short_open_response\", \"prompt\": \"Create a narrative story about Galang and his friends going birdwatching. Your story must answer the 5W+1H: Who went? What did they see? Where did they go? When did they start? Why did they go? How did they feel?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 8, \"max_chars\": 900, \"fingerprint\": \"a16d8e54d517a54cc4cc366e65988df64de898b75deaa21f56c5d2015ba21660\", \"instruction\": \"Berikan rekomendasi singkat dalam bahasa Inggris.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}, {\"id\": 1389, \"type\": \"short_open_response\", \"prompt\": \"Create a narrative about a student named Pipit who writes a blog post about endangered animals. Your story must answer: What animal does she write about? Why is it special? How do her friends help her?\", \"context\": \"This lesson is about Chapter 1 - Exploring Fauna of Indonesia (Unit 1.. You have learned about Indonesian endemic animals such as Cendrawasih, Helmeted Hornbill, and Bali Starling, including their habitats, physical features, and threats.\", \"guidance\": \"\", \"position\": 9, \"max_chars\": 900, \"fingerprint\": \"e5ed7f9e10df446ddb204d998ad586c7d03f20a92f63b1f24453ac0056b48362\", \"instruction\": \"Tulislah pendapat singkat dalam dua sampai tiga kalimat.\", \"example_answer\": \"The Cendrawasih is a beautiful endemic bird found in Papua, Indonesia. It is known for its colourful feathers, which are used by the male to attract females. Unfortunately, Cendrawasih is threatened by habitat destruction and illegal hunting. Therefore, conservation efforts are very important to protect this species.\", \"sentence_starter\": \"\"}]', '1', 'active', '2026-08-02 16:48:09', '2026-08-02 16:48:39', '2026-08-02 16:47:38', NULL, '59e838e369f5aeba2d56b1c5d76dda208dc8209d6944be511e8ed7cf4ed2cef0');
